const telemetry = $('Webhook Trigger').item.json.body;
const analysis = JSON.parse($json.text);
const riskLevel = analysis.riskLevel;

// Spending & action policies
const autoApproveActions = [
  "request_checkin",
  "retrieve_last_location",
  "check_route",
  "check_weather",
  "log_incident"
];

const requireApprovalActions = [
  "contact_roadside_assistance",
  "notify_emergency_contacts",
  "find_assistance"
];

const actionResults = analysis.recommendedActions.map(action => {
  if (autoApproveActions.includes(action)) {
    return { action, authorized: true, reason: 'Auto-approved by policy.', requiresApproval: false };
  }
  if (requireApprovalActions.includes(action)) {
    if (riskLevel === 'CRITICAL') {
      return { action, authorized: true, reason: 'Auto-authorized due to CRITICAL risk.', requiresApproval: false };
    }
    return { action, authorized: false, reason: 'Requires traveler approval.', requiresApproval: true };
  }
  return { action, authorized: false, reason: 'Unknown action. Denied.', requiresApproval: true };
});

const isRoadsideAssistanceApproved = actionResults.some(ar => ar.action === 'contact_roadside_assistance' && ar.authorized);

return {
  telemetry,
  analysis: {
    ...analysis,
    recommendedActions: actionResults
  },
  isRoadsideAssistanceApproved
};

